"Several components on our dashboard load the same user, and each one fires its own request. Build a small \`useQuery\`-style data-fetching helper: components that ask for the same key should share one cached result and one in-flight request, and a failed request should retry a few times with backoff before showing an error. No libraries; a fake fetcher is fine."

